  suspend fun transcribe(clientId: Long, path: String, language: LanguageMsg): TranscriptMsg
  suspend fun chatComplete(clientId: Long, messages: List<ChatMessageMsg>, options: ChatOptionsMsg): ChatResultMsg
  /** Returns a session id. Events: [ChatDeltaMsg]. */
