  /**
   * Returns a session id. Events: [LiveReadyMsg], [LivePartialMsg],
   * [LiveFinalMsg].
   */
  fun startLive(clientId: Long, language: LanguageMsg): String
  /** Returns a session id. Events: the `Voice*Msg` classes. */
  fun startVoice(clientId: Long, language: LanguageMsg, history: List<ChatMessageMsg>, options: ChatOptionsMsg, autoStop: Boolean): String
  /** Graceful finish for live and voice sessions (Kotlin `stop()`). */
  fun stopSession(sessionId: String)
  /** Aborts a session that Dart never listened to, or no longer wants. */
  fun cancelSession(sessionId: String)
  fun hasMicPermission(): Boolean

  companion object {
    /** The codec used by NAtlasHostApi. */
    val codec: MessageCodec<Any?> by lazy {
      MessagesPigeonCodec()
    }
    /** Sets up an instance of `NAtlasHostApi` to handle messages through the `binaryMessenger`. */
