      val separatedMessageChannelSuffix = if (messageChannelSuffix.isNotEmpty()) ".$messageChannelSuffix" else ""
      run {
        val channel = BasicMessageChannel<Any?>(binaryMessenger, "dev.flutter.pigeon.natlas_sdk.NAtlasHostApi.createClient$separatedMessageChannelSuffix", codec)
        if (api != null) {
          channel.setMessageHandler { message, reply ->
            val args = message as List<Any?>
            val configArg = args[0] as ConfigMsg
            val wrapped: List<Any?> = try {
              listOf(api.createClient(configArg))
            } catch (exception: Throwable) {
              MessagesPigeonUtils.wrapError(exception)
